                            + " planned_complete_at, pre_risk_status,"
                            + " created_by, done_by, done_at, cancelled_by, cancelled_at,"
                            + " created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    Statement.RETURN_GENERATED_KEYS);
