@Transactional
public CredentialView revokeCredential(String resourceKey, String credentialCode, String actor, CredentialRevokeRequest req) {
    String commandKey = requireText(req.commandKey(), "commandKey");
    String code = requireText(credentialCode, "credentialCode");
    leases.lockDomain();
    Resource resource = lockResource(resourceKey);
    return idem.run(commandKey, "credential_revoke", hash(resourceKey, actor, code), CredentialView.class, () -> {
        ResourceCredential cred = resources.findCredential(resource.id(), code)
            .orElseThrow(() -> ApiException.notFound("资质不存在: " + code));
        if (cred.revoked()) throw ApiException.conflict("资质已撤销: " + code);
        Instant now = now();
        resources.revokeCredential(resource.id(), code, now);
        resources.bumpVersion(resource.id(), now);
        // 未来有效的高危租约转入 CREDENTIAL_RISK 并写不可变风险记录；已完成任务不改写
        for (ResourceLease lease : leases.listFutureHoldingByResource(resource.id(), now)) {
            if (!lease.credentialCodes().contains(code)) continue;
            int updated = tasks.markCredentialRisk(lease.taskId(), now);
            if (updated == 0) {
                // 任务已并发进入终态：租约释放，不写风险记录
                leases.updateStatus(lease.id(), LeaseStatus.RELEASED, null, now);
                continue;
            }
            leases.updateStatus(lease.id(), LeaseStatus.CREDENTIAL_RISK, null, now);
            leases.insertRiskRecord(new CredentialRiskRecord(0L, lease.id(), lease.taskId(), resource.id(), code, now, now));
        }
        return toCredentialView(resources.findCredential(resource.id(), code).orElseThrow());
    });
}
```

