        // 非高危任务
        incidentService.createTask("INC-D3", "alice",
                new TaskCreateRequest(key(), "T-PLAIN", "G", "t", List.of()));

        // 非高危任务不能分配租约 → 400
        assertApiStatus(() -> assign(key(), "RES-D", T0, T0.plusSeconds(3600),
